export interface Size {
  w: number;
  h: number;
}

/**
 * Bucket list as generated by kohya-ss sd-scripts (`make_bucket_resolutions`): widths from
 * minSize to maxSize in `step` increments, height = largest multiple of `step` keeping
 * w×h ≤ the base area, plus the square bucket. Sorted by aspect ratio (w/h).
 */
export function kohyaBuckets(base: number, minSize = 256, maxSize = base * 2, step = 64): Size[] {
  const maxArea = base * base;
  const seen = new Set<string>();
  const out: Size[] = [];
  const add = (w: number, h: number) => {
    const k = `${w}x${h}`;
    if (seen.has(k)) return;
    seen.add(k);
    out.push({ w, h });
  };
  const sq = Math.floor(Math.sqrt(maxArea) / step) * step;
  add(sq, sq);
  for (let w = minSize; w <= maxSize; w += step) {
    const h = Math.min(maxSize, Math.floor(Math.floor(maxArea / w) / step) * step);
    if (h >= minSize) {
      add(w, h);
      add(h, w);
    }
  }
  return out.sort((a, b) => a.w / a.h - b.w / b.h || a.w - b.w);
}

/** kohya's choice: the bucket with the smallest absolute aspect-ratio error. */
export function nearestBucket(w: number, h: number, buckets: readonly Size[]): Size {
  if (!buckets.length) throw new Error('empty bucket list');
  const ar = w / h;
  let best = buckets[0];
  let err = Infinity;
  for (const b of buckets) {
    const e = Math.abs(b.w / b.h - ar);
    if (e < err) {
      err = e;
      best = b;
    }
  }
  return best;
}

/** Largest multiple of `m` not above `v` (at least `m`). */
export function snapDown(v: number, m: number): number {
  return m <= 1 ? Math.max(1, Math.floor(v)) : Math.max(m, Math.floor(v / m) * m);
}

/** Largest w×h with the given aspect ratio that fits in maxW×maxH. */
export function fitAspect(maxW: number, maxH: number, aspect: number): Size {
  return maxW / maxH > aspect ? { w: maxH * aspect, h: maxH } : { w: maxW, h: maxW / aspect };
}

/** Rotates (dx, dy) to the nearest multiple of `stepDeg`, keeping its length. */
export function snapAngle(dx: number, dy: number, stepDeg = 15): { dx: number; dy: number } {
  const len = Math.hypot(dx, dy);
  if (!len) return { dx, dy };
  const step = (stepDeg * Math.PI) / 180;
  const a = Math.round(Math.atan2(dy, dx) / step) * step;
  return { dx: Math.cos(a) * len, dy: Math.sin(a) * len };
}
